  ROW('Khối B', 'ANH', '1.00', 3),
  ROW('Khối B', 'SU', '1.00', 2),
  ROW('Khối B', 'GDTC', '1.00', 2),
  ROW('Khối B', 'QPAN', '1.00', 1),
  ROW('Khối B', 'HDTN', '1.00', 3),
  ROW('Khối B', 'HOA', '2.00', 3),
  ROW('Khối B', 'SINH', '2.00', 3),
  ROW('Khối B', 'LY', '1.00', 2),
  ROW('Khối B', 'DIA', '1.00', 2),
  ROW('Khối C', 'TOAN', '1.00', 3),
  ROW('Khối C', 'VAN', '2.00', 4),
  ROW('Khối C', 'ANH', '1.00', 3),
  ROW('Khối C', 'SU', '2.00', 3),
  ROW('Khối C', 'GDTC', '1.00', 2),
  ROW('Khối C', 'QPAN', '1.00', 1),
  ROW('Khối C', 'HDTN', '1.00', 3),
  ROW('Khối C', 'DIA', '2.00', 3),
  ROW('Khối C', 'KTPL', '1.00', 2),
  ROW('Khối C', 'TIN', '1.00', 2),
  ROW('Khối C', 'CN', '1.00', 2),
  ROW('Khối D', 'TOAN', '2.00', 4),
  ROW('Khối D', 'VAN', '2.00', 4),
  ROW('Khối D', 'ANH', '2.00', 4),
  ROW('Khối D', 'SU', '1.00', 2),
  ROW('Khối D', 'GDTC', '1.00', 2),
  ROW('Khối D', 'QPAN', '1.00', 1),
  ROW('Khối D', 'HDTN', '1.00', 3),
  ROW('Khối D', 'LY', '1.00', 2),
  ROW('Khối D', 'DIA', '1.00', 2),
  ROW('Khối D', 'KTPL', '1.00', 2),
  ROW('Khối D', 'TIN', '1.00', 2)
) AS v(track_name, subject_code, weight, periods)
JOIN class_tracks t ON t.track_name = v.track_name
JOIN subjects s ON s.subject_code = v.subject_code;

